import { RadialBarChart, RadialBar, Legend } from 'recharts';

const ProgressChart = ({ gains, investment }) => {
  const percent = (gains / investment) * 100;

  const data = [{
    name: 'Progression',
    uv: percent,
    fill: '#82ca9d',
  }];

  return (
    <RadialBarChart width={300} height={200} innerRadius="80%" outerRadius="100%" data={data} startAngle={180} endAngle={0}>
      <RadialBar minAngle={15} background clockWise dataKey="uv" />
      <Legend iconSize={10} layout="vertical" verticalAlign="middle" />
    </RadialBarChart>
  );
};
